def count_divisors(num):
    if num <= 0:
        return 0
    count = 0
    for i in range(1, int(num**0.5) + 1):
        if num % i == 0:
            if i * i == num:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """d(n) is the number of positive divisors of n other than 1 and itself."""
    if n <= 1:
        return 0 # For n=1, divisors are {1}. d(1) should be 0.
    tau_n = count_divisors(n)
    return tau_n - 2

