def get_tau(n):
    if n <= 0:
        return 0
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    tau = 1
    for exponent in factors.values():
        tau *= (exponent + 1)
    return tau

def d(n):
    if n <= 1:
        return 0
    return get_tau(n) - 2

